"""Like calibrate_score.py, but over sev_cases_v2.json (60 cases, generated by
generate_sev_cases.py from sev_rubric.md -- label decided BEFORE the content, script
preserved). See calibrate_score.py for the full derivation of the head.bin packing.

Changes vs v1: N=60 (30/30 in the holdout, was 15/15), `source` metadata points to the generator/rubric.
"""
import sys, os, json, struct
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np
import three_modes as T

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
IN = f"{ROOT}/sev_cases_v2.json"
OUT = f"{ROOT}/head_score_v2.bin"
D, H = 256, 2560
LAMS = [1e0, 1e1, 1e2, 1e3, 1e4]
ALPHA = 1.1

d = json.load(open(IN))
N = len(d)
HALF = N // 2
Y = np.array([x["sev"] for x in d], float)
FD = np.array([x["dec"] for x in d], float)
FL = np.array([x["last"] for x in d], float)
FEATS = {"dec": (FD, None), "last": (None, FL), "concat": (FD, FL)}


def spear(a, b):
    def rankdata(x):
        x = np.asarray(x, float); o = np.argsort(x, kind="mergesort"); r = np.empty(len(x)); i = 0
        while i < len(x):
            j = i
            while j + 1 < len(x) and x[o[j + 1]] == x[o[i]]: j += 1
            r[o[i:j + 1]] = (i + j) / 2.0 + 1; i = j + 1
        return r
    ra, rb = rankdata(a), rankdata(b)
    return float(np.corrcoef(ra, rb)[0, 1])


def X_of(fd, fl, idx):
    parts = [p[idx] for p in (fd, fl) if p is not None]
    return np.hstack(parts)


def ridge_dual(X, y, lam):
    mu = X.mean(0); ym = y.mean(); Xc = X - mu
    a = np.linalg.solve(Xc @ Xc.T + lam * np.eye(len(X)), y - ym)
    w = Xc.T @ a
    return w, ym - mu @ w


def pick_lam(X, y):
    best, bl = 1e18, None
    for lam in LAMS:
        err = 0.0
        for i in range(len(X)):
            m = np.arange(len(X)) != i
            w, b = ridge_dual(X[m], y[m], lam)
            err += (X[i] @ w + b - y[i]) ** 2
        if err < best: best, bl = err, lam
    return bl


def build_head(w_dec, w_last, b, alpha=ALPHA):
    q = np.zeros((D, H), np.float16); qb = np.zeros(D, np.float16)
    k = np.zeros((D, H), np.float16); kb = np.zeros(D, np.float16)
    if w_last is not None:
        s0 = 1.0 / max(1e-12, np.abs(alpha * w_last).max())
        k[0] = alpha * s0 * w_last; qb[0] = 1.0 / s0
    if w_dec is not None:
        s1 = 1.0 / max(1e-12, np.abs(alpha * w_dec).max(), abs(alpha * (b - 3)))
        q[1] = alpha * s1 * w_dec; qb[1] = alpha * s1 * (b - 3); kb[1] = 1.0 / s1
    else:
        qb[1] = alpha * (b - 3); kb[1] = 1.0
    for a in (q, qb, k, kb):
        assert np.isfinite(a.astype(np.float32)).all(), "overflow fp16"
    meta = {"headDim": D, "hiddenSize": H, "temperature": 1.0, "score_offset": 0.0,
            "kind": "score-ridge-v2", "alpha": alpha,
            "source": "calibrate_score_v2.py / sev_cases_v2.json (generate_sev_cases.py + sev_rubric.md, label-before-content, generator preserved)"}
    return meta, q, qb, k, kb


def write_head(path, parts):
    meta, *arrs = parts
    js = json.dumps(meta).encode()
    with open(path, "wb") as f:
        f.write(struct.pack("<I", len(js))); f.write(js)
        for a in arrs: f.write(a.astype("<f2").tobytes())


def fit(name, idx, y):
    fd, fl = FEATS[name]
    X = X_of(fd, fl, idx)
    lam = pick_lam(X, y)
    w, b = ridge_dual(X, y, lam)
    alpha = ALPHA
    wd = w[:H] if fd is not None else None
    wl = (w[H:] if fd is not None else w) if fl is not None else None
    return wd, wl, b, lam, alpha


def eval_head(path, idx):
    hd = T.load_head(path)
    raw = np.array([T.head_score(hd, FD[i], FL[i]) for i in idx])
    lev = np.array([T.to_level(r, 5) for r in raw])
    return raw, lev


TMP = f"{ROOT}/results/_fold_head_v2.bin"
os.makedirs(f"{ROOT}/results", exist_ok=True)


def holdout(name, trials, shuffle=False, seed=7):
    rng = np.random.default_rng(seed)
    sp, ex, w1, lams = [], [], [], []
    for _ in range(trials):
        idx = rng.permutation(N); tr, te = idx[:HALF], idx[HALF:]
        ytr = rng.permutation(Y[tr]) if shuffle else Y[tr]
        wd, wl, b, lam, al = fit(name, tr, ytr)
        write_head(TMP, build_head(wd, wl, b, al))
        raw, lev = eval_head(TMP, te)
        sp.append(spear(Y[te], raw)); ex.append(float((lev == Y[te]).mean()))
        w1.append(float((np.abs(lev - Y[te]) <= 1).mean())); lams.append(lam)
    return dict(spearman_mean=float(np.mean(sp)), spearman_p05=float(np.percentile(sp, 5)),
                frac_gt_05=float(np.mean(np.array(sp) > 0.5)), exact=float(np.mean(ex)),
                within1=float(np.mean(w1)), lam_mode=float(max(set(lams), key=lams.count)))


if __name__ == "__main__":
    report = {"n": N, "per_level": N // 5, "alpha": ALPHA, "lams": LAMS,
              "method": "holdout %d/%d, lambda by LOO on the training split, fixed alpha, evaluated via load_head/head_score/to_level" % (HALF, N - HALF),
              "source": "sev_cases_v2.json (generate_sev_cases.py, label before content, 16 cai-lite classes covered, script preserved)"}
    for name in ("dec", "last", "concat"):
        r = holdout(name, 300)
        c = holdout(name, 100, shuffle=True, seed=11)
        report[name] = r; report[name + "_shuffled"] = c
        print("%-6s spearman %.3f (p05 %.3f, >0.5 %3.0f%%) exact %.3f +-1 %.3f lam %g | shuffled spearman %+.3f exact %.3f"
              % (name, r["spearman_mean"], r["spearman_p05"], 100 * r["frac_gt_05"], r["exact"],
                 r["within1"], r["lam_mode"], c["spearman_mean"], c["exact"]), flush=True)
    report["baseline_always_3"] = 0.2

    best = max(("dec", "last", "concat"), key=lambda k: report[k]["spearman_mean"])
    wd, wl, b, lam, al = fit(best, np.arange(N), Y)
    parts = build_head(wd, wl, b, al)
    parts[0]["features"] = best; parts[0]["lambda"] = lam
    write_head(OUT, parts)

    raw, lev = eval_head(OUT, np.arange(N))
    X = X_of(*FEATS[best], np.arange(N))
    w = np.concatenate([p for p in (wd, wl) if p is not None])
    ref = al * (X @ w + b - 3)
    report["final"] = dict(features=best, lam=lam, alpha=al, bytes=os.path.getsize(OUT),
                           max_abs_err_vs_float64=float(np.abs(raw - ref).max()),
                           in_sample_spearman=spear(Y, raw), in_sample_exact=float((lev == Y).mean()))
    print("final:", report["final"])
    json.dump(report, open(f"{ROOT}/results/calibrate_score_v2.json", "w"), indent=1)
    os.remove(TMP)

